changeSet.sql:
CREATE TABLE public.product (
    id           BIGINT       NOT NULL,
    created_date TIMESTAMP(6),
    updated_date TIMESTAMP(6),
    name         VARCHAR(255) NOT NULL,
    description  VARCHAR(255) NOT NULL,
    CONSTRAINT pk_product PRIMARY KEY (id),
    CONSTRAINT uq_product_name UNIQUE (name)
);

CREATE SEQUENCE public.product_id_generator START WITH 1 INCREMENT BY 1;

CREATE TABLE stop_factors.stop_factor_check ( id BIGINT NOT NULL, created_date TIMESTAMP(6), updated_date TIMESTAMP(6), scoring_id BIGINT NOT NULL, stop_factor_id BIGINT NOT NULL, checked_value TEXT NOT NULL, result VARCHAR(255) NOT NULL, CONSTRAINT pk_stop_factor_check PRIMARY KEY (id), CONSTRAINT fk_stop_factor_check_stop_factor FOREIGN KEY (stop_factor_id) REFERENCES stop_factors.stop_factor (id), CONSTRAINT ck_stop_factor_check_result CHECK (result IN ('APPROVED', 'REJECTED', 'UNDERWRITER')) );
CREATE INDEX idx_stop_factor_check_scoring_id ON stop_factors.stop_factor_check (scoring_id);
CREATE SEQUENCE public.stop_factor_check_id_generator START WITH 1 INCREMENT BY 1;
